{"command": "cd /root/work && python3 -c "
import os
from PIL import Image
import numpy as np
files = sorted(os.listdir('frames'))
prev = None
diffs = []
for f in files:
    img = np.asarray(Image.open(f'frames/{f}').convert('L'), dtype=np.int16)
    if prev is not None:
        diffs.append(float(np.mean(np.abs(img - prev))))
    else:
        diffs.append(0.0)
    prev = img
for i, d in enumerate(diffs):
    t = i*5
    marker = '  <-- CHANGE' if d > 5 else ''
    if d > 1 or i < 5 or i > 110:
        print(f'{t:4d}s  diff={d:7.3f}{marker}')
"", "security_risk": "LOW", "summary": "Find frames where video changes"}

